<header class="page-header"><div><p class="eyebrow">External access</p><h1>Integrations</h1><p>Tokens are assigned to your account, stored only as hashes, and can be revoked immediately.</p></div><a class="button" href="<?= $escape($newUrl) ?>">Create token</a></header><?php if(!$tokenEnabled): ?><p class="validation-summary">Local integration-token authentication is disabled. Tokens can be created now but cannot authenticate an API or MCP request until the environment enables it.</p><?php endif; ?><?php if($integrations===[]): ?><section class="empty-state"><h2>No integration tokens</h2><p>Create a scoped token for a future API or MCP client.</p></section><?php else: ?><div class="table-scroll"><table><thead><tr><th>Name</th><th>Token prefix</th><th>Scopes</th><th>Expires</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($integrations as $item): ?><tr><th><?= $escape($item['display_name']) ?></th><td><?= $escape($item['token_prefix']??'—') ?></td><td><?= $escape(implode(', ',json_decode($item['maximum_scopes_json'],true)?:[])) ?></td><td><?= $escape($item['expires_at']??'—') ?></td><td><?= $item['revoked_at']===null&&$item['token_revoked_at']===null?'Active':'Revoked' ?></td><td><?php if($item['revoked_at']===null): ?><form method="post" action="<?= $escape($revokeUrl((int)$item['id'])) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><input type="hidden" name="version" value="<?= $escape($item['version']) ?>"><label class="visually-hidden">Reason<input name="reason" value="Owner revocation"></label><button class="button--danger">Revoke</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
